//! Metadata-only scan of ~/.claude: names, sizes and dates, never content.
//!
//! Group (a) is obviously redundant, group (b) is generated by Claude Code and
//! cleanable by age, group (c) is never touched. Anything not recognised falls
//! into (c): the scan fails closed.

use serde::Serialize;
use std::fs;
use std::path::{Component, Path};
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use walkdir::WalkDir;

pub const CUTOFFS: [u32; 3] = [7, 30, 90];
const DAY: u64 = 86_400;

/// Why an entry is in group (c); the screen words each kind.
#[derive(Debug, Clone, Copy, Serialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum Reason {
    Config,
    KeptList,
    Credential,
    Unclassified,
}

#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
pub struct Entry {
    pub path: String,
    pub size: u64,
    pub mtime: i64,
    pub reason: Option<Reason>,
}

#[derive(Debug, Clone, Default, Serialize, PartialEq, Eq)]
pub struct Groups {
    pub redundant: Vec<Entry>,
    pub aged: Vec<Entry>,
    pub never_touch: Vec<Entry>,
}

#[derive(Debug, Clone, Serialize, PartialEq, Eq)]
pub struct CleanupScan {
    pub cutoff_days: u32,
    pub groups: Groups,
}

const CONFIG_DIRS: [&str; 15] = [
    "agents",
    "refs",
    "skills",
    "commands",
    "scripts",
    "hooks",
    "templates",
    "code-style",
    "docs",
    "memory",
    "plugins",
    "sessions",
    "session-env",
    "state",
    "ide",
];

fn credential_like(n: &str) -> bool {
    n.starts_with("gitlab-user.txt")
        || n.ends_with(".key")
        || n.starts_with(".credentials")
        || n.starts_with(".env")
}

/// A name that is never touched wherever it appears: any `.bak` or `-bak`
/// (this covers the user-kept list of check-ruleset.sh, which also names
/// `settings.json.empty-bak`, and every future backup) and credential-like names.
fn name_reason(n: &str) -> Option<Reason> {
    if n.contains(".bak") || n.contains("-bak") {
        Some(Reason::KeptList)
    } else if credential_like(n) {
        Some(Reason::Credential)
    } else {
        None
    }
}

/// A top-level zip or tmp output is always redundant, whatever its age: Claude
/// Code writes neither and nothing reads them. Files inside `backups/` are
/// different (the user chose "backups cũ"): they are redundant only past the cut-off.
fn is_redundant_file(n: &str) -> bool {
    n.ends_with(".zip") || (n.starts_with("tmp_") && n.ends_with("_out.txt"))
}

fn top_reason(n: &str) -> Reason {
    if CONFIG_DIRS.contains(&n)
        || n.ends_with(".md")
        || n == "settings.json"
        || n.starts_with("daemon")
    {
        Reason::Config
    } else {
        Reason::Unclassified
    }
}

/// `Some(reason)` when `path` must never be moved to the Trash; `None` only
/// for the shapes the cleanup may offer: a top-level zip or tmp output, a file
/// inside `backups/`, an entry of `worktrees/`, and a session transcript or
/// its same-stem folder under `projects/<folder>/`.
pub fn never_touch_reason(root: &Path, path: &Path) -> Option<Reason> {
    let Ok(rel) = path.strip_prefix(root) else {
        return Some(Reason::Unclassified);
    };
    let mut names: Vec<String> = Vec::new();
    for c in rel.components() {
        match c {
            Component::Normal(n) => names.push(n.to_string_lossy().to_string()),
            _ => return Some(Reason::Unclassified),
        }
    }
    let Some(top) = names.first().cloned() else {
        return Some(Reason::Config);
    };
    if let Some(r) = names.iter().find_map(|n| name_reason(n)) {
        return Some(r);
    }
    match (top.as_str(), names.len()) {
        ("projects", 3) => {
            let name = &names[2];
            if name == "memory" {
                Some(Reason::Config)
            } else if name.ends_with(".jsonl")
                || root
                    .join("projects")
                    .join(&names[1])
                    .join(format!("{name}.jsonl"))
                    .is_file()
            {
                None
            } else {
                Some(Reason::Unclassified)
            }
        }
        ("projects", n) if n < 3 => Some(Reason::Config),
        ("projects", _) => Some(Reason::Unclassified),
        ("worktrees", 2) | ("backups", 2) => None,
        (t, 1) if is_redundant_file(t) => None,
        (t, _) => Some(top_reason(t)),
    }
}

fn secs(t: SystemTime) -> i64 {
    t.duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

/// Total size of the files under `path` and the newest modification time of
/// those files; a folder with no file falls back to its own time.
fn tree(path: &Path) -> (u64, SystemTime) {
    let mut size = 0;
    let mut newest: Option<SystemTime> = None;
    for e in WalkDir::new(path)
        .follow_links(false)
        .into_iter()
        .filter_map(|e| e.ok())
    {
        if let Ok(m) = e.metadata() {
            if m.is_file() {
                size += m.len();
                if let Ok(t) = m.modified() {
                    newest = Some(newest.map_or(t, |n| n.max(t)));
                }
            }
        }
    }
    let own = fs::symlink_metadata(path)
        .and_then(|m| m.modified())
        .unwrap_or(UNIX_EPOCH);
    (size, newest.unwrap_or(own))
}

fn entry(path: &Path, meta: &fs::Metadata, reason: Option<Reason>) -> Entry {
    let (size, t) = if meta.is_dir() {
        tree(path)
    } else {
        (meta.len(), meta.modified().unwrap_or(UNIX_EPOCH))
    };
    Entry {
        path: path.to_string_lossy().to_string(),
        size,
        mtime: secs(t),
        reason,
    }
}

fn children(dir: &Path) -> Vec<(std::path::PathBuf, String, fs::Metadata)> {
    let Ok(rd) = fs::read_dir(dir) else {
        return Vec::new();
    };
    rd.filter_map(|e| e.ok())
        .filter_map(|e| {
            let meta = fs::symlink_metadata(e.path()).ok()?;
            Some((e.path(), e.file_name().to_string_lossy().to_string(), meta))
        })
        .collect()
}

fn scan_projects(dir: &Path, cutoff: i64, g: &mut Groups) {
    for (folder, fname, fmeta) in children(dir) {
        if let Some(r) = name_reason(&fname) {
            g.never_touch.push(entry(&folder, &fmeta, Some(r)));
            continue;
        }
        if !fmeta.is_dir() {
            g.never_touch
                .push(entry(&folder, &fmeta, Some(Reason::Unclassified)));
            continue;
        }
        for (item, name, meta) in children(&folder) {
            if let Some(r) = name_reason(&name) {
                g.never_touch.push(entry(&item, &meta, Some(r)));
            } else if meta.is_file() && name.ends_with(".jsonl") {
                let e = entry(&item, &meta, None);
                if e.mtime < cutoff {
                    g.aged.push(e);
                    let stem_dir = folder.join(name.trim_end_matches(".jsonl"));
                    if let Ok(m) = fs::symlink_metadata(&stem_dir) {
                        if m.is_dir() {
                            g.aged.push(entry(&stem_dir, &m, None));
                        }
                    }
                }
            } else if meta.is_dir() && folder.join(format!("{name}.jsonl")).is_file() {
                // decided together with its transcript above
            } else if meta.is_dir() && name == "memory" {
                g.never_touch
                    .push(entry(&item, &meta, Some(Reason::Config)));
            } else {
                g.never_touch
                    .push(entry(&item, &meta, Some(Reason::Unclassified)));
            }
        }
    }
}

fn scan_worktrees(dir: &Path, cutoff: i64, g: &mut Groups) {
    for (item, name, meta) in children(dir) {
        if let Some(r) = name_reason(&name) {
            g.never_touch.push(entry(&item, &meta, Some(r)));
            continue;
        }
        let e = entry(&item, &meta, None);
        if e.mtime < cutoff {
            g.aged.push(e);
        }
    }
}

/// Files of `backups/` are redundant only when older than the cut-off, unlike
/// the always-redundant top-level zip and tmp outputs.
fn scan_backups(dir: &Path, cutoff: i64, g: &mut Groups) {
    for (item, name, meta) in children(dir) {
        if let Some(r) = name_reason(&name) {
            g.never_touch.push(entry(&item, &meta, Some(r)));
        } else if meta.is_file() {
            let e = entry(&item, &meta, None);
            if e.mtime < cutoff {
                g.redundant.push(e);
            }
        }
    }
}

/// Group the entries of `root` (normally ~/.claude) for a cut-off of 7, 30 or
/// 90 days. Reads names, sizes and dates only.
pub fn scan(root: &Path, cutoff_days: u32, now: SystemTime) -> std::io::Result<CleanupScan> {
    let cutoff_t = now
        .checked_sub(Duration::from_secs(cutoff_days as u64 * DAY))
        .unwrap_or(UNIX_EPOCH);
    let cutoff = secs(cutoff_t);
    let mut g = Groups::default();
    for e in fs::read_dir(root)?.filter_map(|e| e.ok()) {
        let path = e.path();
        let name = e.file_name().to_string_lossy().to_string();
        let Ok(meta) = fs::symlink_metadata(&path) else {
            continue;
        };
        if let Some(r) = name_reason(&name) {
            g.never_touch.push(entry(&path, &meta, Some(r)));
            continue;
        }
        match name.as_str() {
            "projects" if meta.is_dir() => scan_projects(&path, cutoff, &mut g),
            "worktrees" if meta.is_dir() => scan_worktrees(&path, cutoff, &mut g),
            "backups" if meta.is_dir() => scan_backups(&path, cutoff, &mut g),
            n if meta.is_file() && is_redundant_file(n) => {
                g.redundant.push(entry(&path, &meta, None))
            }
            n => g.never_touch.push(entry(&path, &meta, Some(top_reason(n)))),
        }
    }
    for list in [&mut g.redundant, &mut g.aged, &mut g.never_touch] {
        list.sort_by(|a, b| a.path.cmp(&b.path));
    }
    Ok(CleanupScan {
        cutoff_days,
        groups: g,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs::File;
    use tempfile::TempDir;

    fn touch(root: &Path, rel: &str, bytes: usize, age_days: u64) {
        let p = root.join(rel);
        fs::create_dir_all(p.parent().unwrap()).unwrap();
        fs::write(&p, vec![b'x'; bytes]).unwrap();
        age(&p, age_days);
    }

    fn age(p: &Path, days: u64) {
        let t = SystemTime::now() - Duration::from_secs(days * DAY);
        File::open(p).unwrap().set_modified(t).unwrap();
    }

    fn names(list: &[Entry], root: &Path) -> Vec<String> {
        list.iter()
            .map(|e| {
                Path::new(&e.path)
                    .strip_prefix(root)
                    .unwrap()
                    .to_string_lossy()
                    .to_string()
            })
            .collect()
    }

    fn fixture() -> TempDir {
        let d = TempDir::new().unwrap();
        let r = d.path();
        touch(r, "skills.zip", 10, 1);
        touch(r, "tmp_audit_scan1_out.txt", 5, 1);
        touch(r, "settings.json.bak.1", 3, 1);
        touch(r, "CLAUDE.md", 3, 1);
        touch(r, "agents/a.md", 3, 1);
        touch(r, "gitlab-user.txt.bak.20260901", 3, 1);
        touch(r, "mystery.dat", 3, 1);
        touch(r, "projects/-p/old.jsonl", 100, 40);
        touch(r, "projects/-p/old/sub.txt", 50, 40);
        age(&r.join("projects/-p/old"), 40);
        touch(r, "projects/-p/new.jsonl", 100, 2);
        touch(r, "projects/-p/memory/m.md", 7, 40);
        touch(r, "worktrees/agent-1/f.txt", 20, 100);
        touch(r, "worktrees/agent-2/f.txt", 20, 1);
        touch(r, "backups/old.tar", 8, 40);
        touch(r, "backups/new.tar", 8, 1);
        d
    }

    #[test]
    fn entries_fall_into_the_three_groups_at_thirty_days() {
        let d = fixture();
        let s = scan(d.path(), 30, SystemTime::now()).unwrap();
        assert_eq!(
            names(&s.groups.redundant, d.path()),
            vec!["backups/old.tar", "skills.zip", "tmp_audit_scan1_out.txt"]
        );
        assert_eq!(
            names(&s.groups.aged, d.path()),
            vec![
                "projects/-p/old",
                "projects/-p/old.jsonl",
                "worktrees/agent-1"
            ]
        );
        let never = names(&s.groups.never_touch, d.path());
        for want in [
            "settings.json.bak.1",
            "CLAUDE.md",
            "agents",
            "gitlab-user.txt.bak.20260901",
            "mystery.dat",
            "projects/-p/memory",
        ] {
            assert!(never.contains(&want.to_string()), "{want} in {never:?}");
        }
        assert!(s.groups.never_touch.iter().all(|e| e.reason.is_some()));
        assert_eq!(s.groups.aged[0].size, 50);
    }

    #[test]
    fn the_cut_off_changes_group_b_exactly_by_modification_time() {
        let d = TempDir::new().unwrap();
        touch(d.path(), "projects/-p/a.jsonl", 1, 10);
        touch(d.path(), "projects/-p/b.jsonl", 1, 50);
        touch(d.path(), "projects/-p/c.jsonl", 1, 100);
        let aged = |days| {
            names(
                &scan(d.path(), days, SystemTime::now()).unwrap().groups.aged,
                d.path(),
            )
        };
        assert_eq!(aged(7).len(), 3);
        assert_eq!(aged(30).len(), 2);
        assert_eq!(aged(90).len(), 1);
    }

    #[test]
    fn an_empty_projects_folder_gives_an_empty_group_b() {
        let d = TempDir::new().unwrap();
        fs::create_dir_all(d.path().join("projects")).unwrap();
        let s = scan(d.path(), 30, SystemTime::now()).unwrap();
        assert!(
            s.groups.aged.is_empty()
                && s.groups.redundant.is_empty()
                && s.groups.never_touch.is_empty()
        );
    }

    #[test]
    fn the_scan_lists_a_file_it_cannot_read_by_metadata_alone() {
        use std::os::unix::fs::PermissionsExt;
        let d = TempDir::new().unwrap();
        touch(d.path(), "locked.zip", 9, 1);
        let p = d.path().join("locked.zip");
        fs::set_permissions(&p, fs::Permissions::from_mode(0o000)).unwrap();
        let s = scan(d.path(), 30, SystemTime::now()).unwrap();
        fs::set_permissions(&p, fs::Permissions::from_mode(0o644)).unwrap();
        assert_eq!(s.groups.redundant.len(), 1);
        assert_eq!(s.groups.redundant[0].size, 9);
    }

    #[test]
    fn never_touch_covers_backups_credentials_config_and_the_unknown() {
        let d = fixture();
        let r = d.path();
        let reason = |rel: &str| never_touch_reason(r, &r.join(rel));
        assert_eq!(reason("settings.json.bak.1"), Some(Reason::KeptList));
        assert_eq!(
            reason("scripts/error-stats.sh.bak-20260907"),
            Some(Reason::KeptList)
        );
        assert_eq!(reason("settings.json.empty-bak"), Some(Reason::KeptList));
        assert_eq!(reason("backups/x-bak"), Some(Reason::KeptList));
        assert_eq!(reason("gitlab-user.txt"), Some(Reason::Credential));
        assert_eq!(reason("id.key"), Some(Reason::Credential));
        assert_eq!(reason("agents/planner.md"), Some(Reason::Config));
        assert_eq!(reason("CLAUDE.md"), Some(Reason::Config));
        assert_eq!(reason("never-seen"), Some(Reason::Unclassified));
        assert_eq!(reason("projects"), Some(Reason::Config));
        assert_eq!(reason("projects/-p"), Some(Reason::Config));
        assert_eq!(reason("projects/-p/memory"), Some(Reason::Config));
        assert_eq!(
            reason("projects/-p/old.jsonl/deeper"),
            Some(Reason::Unclassified)
        );
        assert_eq!(
            never_touch_reason(r, Path::new("/etc/passwd")),
            Some(Reason::Unclassified)
        );
        assert_eq!(
            never_touch_reason(r, &r.join("../escape")),
            Some(Reason::Unclassified)
        );
        // the shapes the cleanup may offer
        assert_eq!(reason("skills.zip"), None);
        assert_eq!(reason("tmp_audit_scan1_out.txt"), None);
        assert_eq!(reason("backups/old.tar"), None);
        assert_eq!(reason("worktrees/agent-1"), None);
        assert_eq!(reason("projects/-p/old.jsonl"), None);
        assert_eq!(reason("projects/-p/old"), None);
    }

    #[test]
    fn everything_offered_in_a_or_b_passes_the_never_touch_guard() {
        let d = fixture();
        let s = scan(d.path(), 7, SystemTime::now()).unwrap();
        for e in s.groups.redundant.iter().chain(&s.groups.aged) {
            assert_eq!(
                never_touch_reason(d.path(), Path::new(&e.path)),
                None,
                "{}",
                e.path
            );
        }
    }
}
